import java.util.Scanner

fun gcd(a: Long, b: Long): Long {
    if (b == 0L) return a
    if (a == 0L) return b
    return if (a < b) gcd(a, b % a) else gcd(b, a % b)
}

fun lcm(a: Long, b: Long): Long {
    val c = gcd(a, b)
    return a / c * b
}

fun bfs(i: Int, visited: BooleanArray, count: Int, index: Int, A: IntArray): Int {
    if (i == index) {
        return if (count % 2 == 1) count else count / 2
    }
    if (!visited[i]) {
        visited[i] = true
        return bfs(A[i], visited, count + 1, index, A)
    }
    return -1
}

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val A = IntArray(n)
    for (i in 0 until n) {
        A[i] = scanner.nextInt() - 1
    }
    val visited = BooleanArray(n)
    var ans = 1L
    var valid = true
    for (i in 0 until n) {
        if (!visited[i]) {
            visited[i] = true
            val cycle = bfs(A[i], visited, 1, i, A)
            if (cycle == -1) {
                ans = -1
                valid = false
                break
            } else {
                ans = lcm(ans, cycle.toLong())
            }
        }
    }
    println(ans)
}

