import java.util.Scanner

fun gcd(a: Long, b: Long): Long {
    return if (b == 0L) a else gcd(b, a % b)
}

fun lcm(a: Long, b: Long): Long {
    val g = gcd(a, b)
    return a / g * b
}

fun findCycleLength(start: Int, visited: BooleanArray, A: IntArray): Int {
    var current = A[start]
    var count = 1
    while (current != start) {
        if (visited[current]) return -1
        visited[current] = true
        current = A[current]
        count++
    }
    return if (count % 2 == 0) count / 2 else count
}

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val A = IntArray(n)
    for (i in 0 until n) {
        A[i] = scanner.nextInt() - 1
    }
    val visited = BooleanArray(n)
    var ans: Long = 1
    for (i in 0 until n) {
        if (!visited[i]) {
            visited[i] = true
            val cycle = findCycleLength(i, visited, A)
            if (cycle == -1) {
                ans = -1
                break
            } else {
                ans = lcm(ans, cycle.toLong())
            }
        }
    }
    println(ans)
}
```

