#include <stdio.h>

long long int GCD(long long int a,long long int b){
	if(b==0)return a;
	if(a==0)return b;
	if(a<b)return(GCD(a,b%a));
	else return(GCD(b,a%b));
}

long long int LCM(long long int a,long long int b){
	long long int c=GCD(a,b);
	return((a/c)*(b/c)*c);
}

int bfs(int i,int visited[],int count,int index,int A[]){
	if(i==index){
		if(count%2)return count;
		else return(count/2);
	}
	if(visited[i]==0){
		visited[i]=1;
		return(bfs(A[i],visited,count+1,index,A));
	}
	return(-1);
}

int main(){
	int i,n,A[105],cycle,visited[105];
	long long int ans;
	scanf("%d",&n);
	for(i=0;i<n;i++){
		scanf("%d",&A[i]);
		A[i]--;
	}
	for(i=0;i<n;i++)visited[i]=0;
	ans=1;
	for(i=0;i<n;i++){
		if(visited[i]==0){
			visited[i]=1;
			cycle=bfs(A[i],visited,1,i,A);
			if(cycle==-1){
				ans=-1;
				break;
			}
			else ans=LCM(ans,(long long int)cycle);
		}
	}
	printf("%lld\n",ans);
	return 0;
}
